* {
    box-sizing: border-box;
}

body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Open Sans", "Helvetica Neue", sans-serif;
    background: #f5f5f5;
    color: #333;
}

.page {
    max-width: 920px;
    margin: 24px auto 40px;
    padding: 0 20px;
}

.page-header {
    margin-bottom: 20px;
}

.page-header h1 {
    margin: 0 0 6px;
    font-size: 26px;
    color: #1a73e8;
}

.page-header p {
    margin: 0;
    color: #5f6368;
    font-size: 14px;
}

.card {
    background: #ffffff;
    border: 1px solid #e0e0e0;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 16px;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
}

.card h2 {
    margin: 0 0 12px;
    font-size: 16px;
    color: #1f1f1f;
}

.field {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin: 10px 0;
    font-size: 14px;
}

.field label {
    color: #333;
}

.field.toggle input {
    transform: scale(1.1);
}

.range-row {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
}

.range-row input[type="range"] {
    flex: 1;
}

.value-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 48px;
    padding: 4px 8px;
    border-radius: 14px;
    background: #e8f0fe;
    color: #1a73e8;
    border: 1px solid #d2e3fc;
    font-size: 12px;
}

.grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
    gap: 12px;
}

.field input[type="number"] {
    width: 100%;
    padding: 6px 8px;
    border-radius: 6px;
    border: 1px solid #dcdcdc;
    font-size: 13px;
}

.note {
    margin: 8px 0 0;
    font-size: 12px;
    color: #666;
}

.actions {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
}

.button {
    border: 1px solid transparent;
    border-radius: 6px;
    padding: 8px 14px;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.2s ease;
}

.button.primary {
    background: #1a73e8;
    color: #fff;
}

.button.primary:hover {
    background: #1557b0;
}

.button.secondary {
    background: #f1f3f4;
    color: #5f6368;
    border-color: #dadce0;
}

.button.secondary:hover {
    background: #e8eaed;
}

@media (max-width: 600px) {
    .field {
        flex-direction: column;
        align-items: stretch;
    }

    .actions {
        flex-direction: column;
        align-items: stretch;
    }
}

document.addEventListener('DOMContentLoaded', () => {
